css:
/* East Texas Mack type and button conventions, applied site-wide.
   Headings are Oswald, uppercase and set tight; buttons and eyebrows are Inter. */
.bz-block :is(h1, h2, h3) { font-weight: var(--weight-heading); text-transform: uppercase; letter-spacing: 0; }
.bz-block h1 { line-height: 1.08; }
.bz-block :is(h2, h3) { line-height: normal; }
.bz-block .bz-eyebrow { font: 700 var(--text-eyebrow) / 1.4 var(--font-body); letter-spacing: 1.5px; margin: 0 0 10px; }
.bz-btn { font-family: var(--font-body); font-weight: 600; border-radius: var(--radius-input); }
.bz-btn--primary { color: var(--card); }
.bz-btn--primary:hover { background: var(--accent-dark); }
.bz-btn--secondary:hover { opacity: .9; }
.bz-btn--link { text-decoration: none; padding: 0; font-size: 15px; color: var(--accent-dark); }
.bz-btn--link:hover { opacity: .8; }

/* ---- Inner pages (components named pg-*) ---------------------------------
   Shared palette and type for the bands. The few tints below are not part of
   the 8-colour design system, so they are named once here instead of repeated. */
:root { --band-tan: #f2f0eb; --ink-raised: #1c1d22; --accent-soft: #8fa3d1; --copy: #4a4d52; --copy-on-dark: #9a9da3; }
[data-bz-section^="pg-"] .bz-block { padding-block: 0; }
[data-bz-section^="pg-"] .bz-section--bg-paper { background: var(--band-tan); }
[data-bz-section^="pg-"] .bz-section--bg-accent { color: var(--card); }
[data-bz-section^="pg-"] .bz-block .bz-eyebrow { color: var(--accent); }
[data-bz-section^="pg-"] .bz-section--bg-ink .bz-block .bz-eyebrow { color: var(--accent-soft); }
[data-bz-section^="pg-"] .bz-headingblock h2 { font-size: 30px; line-height: normal; margin: 0 0 20px; }
[data-bz-section^="pg-"] .bz-section--bg-ink .bz-block .copy__p, [data-bz-section^="pg-"] .bz-section--bg-ink .bz-block .copy__ul { color: var(--copy-on-dark); }
[data-bz-section^="pg-"] .bz-section--bg-ink .bz-block .copy__ul--bars li { border-left-color: var(--bad); color: #e5e6e8; font-size: 15px; }
[data-bz-section^="pg-"] .bz-section--bg-ink .bz-block .copy__p--note { color: var(--accent-soft); }
[data-bz-section^="pg-"] .bz-btns { margin: 0; gap: 16px; align-items: center; }
[data-bz-section^="pg-"] .bz-btn--primary { background: var(--bad); color: var(--card); font: 600 15px / normal var(--font-body); padding: 15px 30px; border-radius: var(--radius-input); }
[data-bz-section^="pg-"] .bz-btn--primary:hover { background: var(--bad); filter: brightness(0.9); }
[data-bz-section^="pg-"] .bz-btn--link { font: 700 14px / normal var(--font-body); color: var(--accent); }
[data-bz-section^="pg-"] .bz-section--bg-ink .bz-btn--link { color: var(--accent-soft); }
[data-bz-section^="pg-"] .bz-block--buttons:has(.bz-btn--link) + .bz-block--buttons:has(.bz-btn--link) .bz-btn--link { border-left: 1px solid rgba(20, 21, 26, 0.2); padding-left: 16px; }
[data-bz-section^="pg-"] .bz-row:has(> .bz-col:empty) { display: none; }
[data-bz-section^="pg-"] .bz-section--bg-ink .bz-block--buttons:has(.bz-btn--link) + .bz-block--buttons:has(.bz-btn--link) .bz-btn--link { border-left-color: rgba(255, 255, 255, 0.25); }
[data-bz-section^="pg-"] .bz-block p.copy__p { margin-bottom: 16px; }
[data-bz-section^="pg-"] .bz-block p.copy__p--label, [data-bz-section^="pg-"] .bz-block p.copy__p--note { margin-bottom: 14px; }

/* ---- Form pages (the "form-band" section on /parts-request, /service-appointments, /finance-credit-application) ---- */
.bz-section[data-bz-node="form-band"] .bz-block { padding-block: 0; }
.bz-section[data-bz-node="form-band"] .bz-form { max-width: none; background: var(--paper); border: 0; border-radius: var(--radius-card); padding: 44px; gap: 24px 16px; box-shadow: 0 2px 12px rgba(0, 0, 0, 0.05); }
.bz-section[data-bz-node="form-band"] .bz-form__t { display: none; }
.bz-section[data-bz-node="form-band"] .bz-label { font: 600 14px / normal var(--font-body); color: var(--ink); }
.bz-section[data-bz-node="form-band"] .bz-req { font-size: 0; }
.bz-section[data-bz-node="form-band"] .bz-req::before { content: "(Required)"; font-size: 14px; font-weight: 400; color: var(--bad); }
.bz-section[data-bz-node="form-band"] .bz-input { font-size: 15px; padding: 13px 14px; min-height: 47px; border-radius: var(--radius-input); }
.bz-section[data-bz-node="form-band"] textarea.bz-input { min-height: 96px; }
.bz-section[data-bz-node="form-band"] .bz-choices { flex-direction: row; flex-wrap: wrap; gap: 8px 24px; }
.bz-section[data-bz-node="form-band"] .bz-help { font-size: 13px; line-height: 1.6; color: var(--copy); margin-top: 12px; }
.bz-section[data-bz-node="form-band"] .bz-btn[type="submit"] { flex: 0 0 auto; background: var(--bad); color: var(--card); font: 700 15px / normal var(--font-body); letter-spacing: 0.3px; padding: 16px 36px; }
@media (max-width: 640px) { .bz-section[data-bz-node="form-band"] .bz-form { padding: 24px 18px; } }
